-- Aprenda se Divertindo · 74 · Cartões da trilha Policial · parte 1 de 5 (cartões 1000001 a 1000100)
-- Cole no SQL Editor e clique em Run. Pode rodar de novo sem problema. Rode as partes em ordem (a parte 1 cria a tabela).

--   • Para desativar um cartão: update public.cartoes set ativa = false where id = NÚMERO;

create table if not exists public.cartoes (
  id            integer primary key check (id >= 1000000),
  trilha        text not null,
  materia       text not null,
  assunto       text not null default '',
  tipo          text not null default 'pergunta' check (tipo in ('pergunta','lacuna','certo_errado','pares')),
  frente        text not null,
  verso         text not null,
  explicacao    text not null default '',
  ativa         boolean not null default true,
  atualizado_em timestamptz not null default now()
);
create index if not exists cartoes_trilha on public.cartoes (trilha) where ativa;

alter table public.cartoes enable row level security;
drop policy if exists "cartoes visiveis" on public.cartoes;
create policy "cartoes visiveis" on public.cartoes for select to anon, authenticated using (ativa);
revoke insert, update, delete on public.cartoes from anon, authenticated;
grant select on public.cartoes to anon, authenticated;

-- "impressão digital" do baralho: o jogo só baixa os cartões de novo quando algo muda
create or replace function public.cartoes_versao()
returns text language sql stable security definer set search_path = '' as $$
  select md5(coalesce(string_agg(md5(concat_ws('|', id, trilha, materia, assunto, tipo, frente, verso, explicacao, ativa)), '' order by id), ''))
  from public.cartoes;
$$;
revoke all on function public.cartoes_versao() from public;
grant execute on function public.cartoes_versao() to anon, authenticated;

insert into public.cartoes (id, trilha, materia, assunto, tipo, frente, verso, explicacao)
select id, trilha, materia, assunto, tipo, frente, verso, explicacao
from jsonb_to_recordset($c$[{"id": 1000001, "trilha": "policial", "materia": "pen", "assunto": "Lei penal", "tipo": "lacuna", "frente": "“Não há crime sem lei ____ que o defina, nem pena sem prévia cominação legal.”", "verso": "anterior", "explicacao": "Princípio da legalidade e da anterioridade: CF, art. 5º, XXXIX, e CP, art. 1º."}, {"id": 1000002, "trilha": "policial", "materia": "pen", "assunto": "Lei penal", "tipo": "pergunta", "frente": "A lei penal mais benéfica retroage mesmo depois do trânsito em julgado?", "verso": "Sim. Retroage para beneficiar o réu, ainda que já condenado em definitivo.", "explicacao": "CP, art. 2º, parágrafo único, e CF, art. 5º, XL."}, {"id": 1000003, "trilha": "policial", "materia": "pen", "assunto": "Lei penal", "tipo": "pergunta", "frente": "Na abolitio criminis, o que acontece com os efeitos civis da condenação?", "verso": "Continuam. Cessam a execução e os efeitos penais, mas os efeitos civis (como o dever de indenizar) permanecem.", "explicacao": "CP, art. 2º, caput."}, {"id": 1000004, "trilha": "policial", "materia": "pen", "assunto": "Lei penal", "tipo": "pergunta", "frente": "Qual teoria o Código Penal adota para o TEMPO do crime?", "verso": "Teoria da atividade: considera-se praticado o crime no momento da ação ou omissão, ainda que outro seja o resultado.", "explicacao": "CP, art. 4º. Mnemônico LUTA: Lugar = Ubiquidade; Tempo = Atividade."}, {"id": 1000005, "trilha": "policial", "materia": "pen", "assunto": "Lei penal", "tipo": "pergunta", "frente": "Qual teoria o Código Penal adota para o LUGAR do crime?", "verso": "Teoria da ubiquidade: lugar da ação ou omissão, no todo ou em parte, e também onde se produziu ou deveria produzir-se o resultado.", "explicacao": "CP, art. 6º. Mnemônico LUTA."}, {"id": 1000006, "trilha": "policial", "materia": "pen", "assunto": "Teoria do crime", "tipo": "pergunta", "frente": "Pelo conceito analítico tripartido, crime é:", "verso": "Fato típico, ilícito (antijurídico) e culpável.", "explicacao": "Teoria tripartida, majoritária na doutrina e cobrada pelas bancas."}, {"id": 1000007, "trilha": "policial", "materia": "pen", "assunto": "Teoria do crime", "tipo": "pergunta", "frente": "Quais são os elementos do fato típico?", "verso": "Conduta, resultado, nexo causal e tipicidade.", "explicacao": "Nos crimes formais e de mera conduta, o resultado naturalístico não é exigido para a consumação."}, {"id": 1000008, "trilha": "policial", "materia": "pen", "assunto": "Excludentes", "tipo": "pergunta", "frente": "Quais são as quatro excludentes de ilicitude do art. 23 do CP?", "verso": "Estado de necessidade, legítima defesa, estrito cumprimento do dever legal e exercício regular de direito.", "explicacao": "CP, art. 23. O excesso doloso ou culposo é punível (parágrafo único)."}, {"id": 1000009, "trilha": "policial", "materia": "pen", "assunto": "Excludentes", "tipo": "lacuna", "frente": "Legítima defesa: quem, usando moderadamente dos meios necessários, repele injusta agressão, ____ ou iminente, a direito seu ou de outrem.", "verso": "atual", "explicacao": "CP, art. 25. Agressão futura ou passada não autoriza legítima defesa."}, {"id": 1000010, "trilha": "policial", "materia": "pen", "assunto": "Excludentes", "tipo": "certo_errado", "frente": "Certo ou errado? Considera-se em legítima defesa o agente de segurança pública que repele agressão ou risco de agressão a vítima mantida refém durante a prática de crimes.", "verso": "Certo.", "explicacao": "CP, art. 25, parágrafo único, incluído pelo Pacote Anticrime (Lei 13.964/2019)."}, {"id": 1000011, "trilha": "policial", "materia": "pen", "assunto": "Excludentes", "tipo": "pergunta", "frente": "Quem tem o dever legal de enfrentar o perigo (ex.: bombeiro) pode alegar estado de necessidade?", "verso": "Não.", "explicacao": "CP, art. 24, § 1º."}, {"id": 1000012, "trilha": "policial", "materia": "pen", "assunto": "Dolo e culpa", "tipo": "pares", "frente": "Qual a diferença entre dolo direto e dolo eventual?", "verso": "Dolo direto: o agente quer o resultado. Dolo eventual: o agente prevê o resultado e assume o risco de produzi-lo.", "explicacao": "CP, art. 18, I."}, {"id": 1000013, "trilha": "policial", "materia": "pen", "assunto": "Dolo e culpa", "tipo": "pares", "frente": "Qual a diferença entre culpa consciente e dolo eventual?", "verso": "Nos dois o agente prevê o resultado. Na culpa consciente, acredita sinceramente que ele não vai acontecer; no dolo eventual, aceita que aconteça (“tanto faz”).", "explicacao": "Diferença clássica de prova: a previsão existe nas duas; o que muda é a aceitação do resultado."}, {"id": 1000014, "trilha": "policial", "materia": "pen", "assunto": "Dolo e culpa", "tipo": "pergunta", "frente": "Quais são as três modalidades de culpa?", "verso": "Imprudência (agir sem cautela), negligência (deixar de agir com cautela) e imperícia (falta de aptidão técnica).", "explicacao": "CP, art. 18, II."}, {"id": 1000015, "trilha": "policial", "materia": "pen", "assunto": "Dolo e culpa", "tipo": "certo_errado", "frente": "Certo ou errado? Todo crime admite a forma culposa.", "verso": "Errado. Só se pune a forma culposa quando a lei a prevê expressamente.", "explicacao": "CP, art. 18, parágrafo único (excepcionalidade do crime culposo)."}, {"id": 1000016, "trilha": "policial", "materia": "pen", "assunto": "Iter criminis", "tipo": "pergunta", "frente": "Qual é a redução de pena na tentativa?", "verso": "De um a dois terços.", "explicacao": "CP, art. 14, parágrafo único. Quanto mais perto da consumação, menor a redução."}, {"id": 1000017, "trilha": "policial", "materia": "pen", "assunto": "Iter criminis", "tipo": "pares", "frente": "Qual a diferença entre desistência voluntária e arrependimento eficaz?", "verso": "Desistência: o agente para no meio da execução. Arrependimento eficaz: termina a execução, mas age para impedir o resultado. Nos dois, responde só pelos atos já praticados.", "explicacao": "CP, art. 15. São a “ponte de ouro”."}, {"id": 1000018, "trilha": "policial", "materia": "pen", "assunto": "Iter criminis", "tipo": "pergunta", "frente": "Quais os requisitos do arrependimento posterior?", "verso": "Crime sem violência ou grave ameaça à pessoa, reparação do dano ou restituição da coisa, por ato voluntário, até o recebimento da denúncia ou queixa. Reduz a pena de 1/3 a 2/3.", "explicacao": "CP, art. 16. É a “ponte de prata”."}, {"id": 1000019, "trilha": "policial", "materia": "pen", "assunto": "Iter criminis", "tipo": "pergunta", "frente": "O que é crime impossível?", "verso": "Quando, por ineficácia absoluta do meio ou absoluta impropriedade do objeto, é impossível consumar o crime. Não se pune nem a tentativa.", "explicacao": "CP, art. 17. Ex.: tentar matar quem já estava morto."}, {"id": 1000020, "trilha": "policial", "materia": "pen", "assunto": "Erro", "tipo": "pares", "frente": "Erro de tipo: qual o efeito quando é inevitável e quando é evitável?", "verso": "Inevitável: exclui dolo e culpa. Evitável: exclui o dolo, mas permite punir por culpa, se houver forma culposa.", "explicacao": "CP, art. 20."}, {"id": 1000021, "trilha": "policial", "materia": "pen", "assunto": "Erro", "tipo": "pares", "frente": "Erro de proibição: qual o efeito quando é inevitável e quando é evitável?", "verso": "Inevitável: isenta de pena. Evitável: reduz a pena de 1/6 a 1/3.", "explicacao": "CP, art. 21. O desconhecimento da lei é inescusável."}, {"id": 1000022, "trilha": "policial", "materia": "pen", "assunto": "Culpabilidade", "tipo": "pergunta", "frente": "Na coação moral irresistível, quem é punido?", "verso": "Só o autor da coação.", "explicacao": "CP, art. 22. Exclui a culpabilidade do coagido (inexigibilidade de conduta diversa)."}, {"id": 1000023, "trilha": "policial", "materia": "pen", "assunto": "Culpabilidade", "tipo": "pergunta", "frente": "A partir de que idade a pessoa é penalmente imputável?", "verso": "18 anos. Os menores ficam sujeitos à legislação especial (ECA).", "explicacao": "CP, art. 27, e CF, art. 228."}, {"id": 1000024, "trilha": "policial", "materia": "pen", "assunto": "Culpabilidade", "tipo": "certo_errado", "frente": "Certo ou errado? A emoção e a paixão excluem a imputabilidade penal.", "verso": "Errado.", "explicacao": "CP, art. 28, I. Podem, no máximo, atenuar a pena ou privilegiar o homicídio."}, {"id": 1000025, "trilha": "policial", "materia": "pen", "assunto": "Culpabilidade", "tipo": "pergunta", "frente": "Que tipo de embriaguez completa isenta de pena?", "verso": "A proveniente de caso fortuito ou força maior. A voluntária ou culposa não exclui a imputabilidade.", "explicacao": "CP, art. 28, II e § 1º (actio libera in causa para a voluntária)."}, {"id": 1000026, "trilha": "policial", "materia": "pen", "assunto": "Concurso de pessoas", "tipo": "pergunta", "frente": "Qual teoria do concurso de pessoas o CP adota como regra?", "verso": "Teoria monista (unitária): todos respondem pelo mesmo crime, na medida de sua culpabilidade.", "explicacao": "CP, art. 29. Há exceções pluralistas, como corrupção ativa e passiva."}, {"id": 1000027, "trilha": "policial", "materia": "pen", "assunto": "Concurso de pessoas", "tipo": "pergunta", "frente": "Qual a redução para a participação de menor importância?", "verso": "De 1/6 a 1/3.", "explicacao": "CP, art. 29, § 1º."}, {"id": 1000028, "trilha": "policial", "materia": "pen", "assunto": "Penas", "tipo": "pergunta", "frente": "Quais são as espécies de pena no CP?", "verso": "Privativas de liberdade, restritivas de direitos e multa.", "explicacao": "CP, art. 32."}, {"id": 1000029, "trilha": "policial", "materia": "pen", "assunto": "Penas", "tipo": "pergunta", "frente": "Qual o tempo máximo de cumprimento das penas privativas de liberdade?", "verso": "40 anos.", "explicacao": "CP, art. 75, com redação do Pacote Anticrime (antes eram 30)."}, {"id": 1000030, "trilha": "policial", "materia": "pen", "assunto": "Penas", "tipo": "pergunta", "frente": "Pena superior a 8 anos: qual o regime inicial?", "verso": "Fechado.", "explicacao": "CP, art. 33, § 2º, a. Mais de 4 até 8 (não reincidente): semiaberto; até 4 (não reincidente): aberto."}, {"id": 1000031, "trilha": "policial", "materia": "pen", "assunto": "Penas", "tipo": "pergunta", "frente": "Quais os requisitos para substituir a prisão por pena restritiva de direitos?", "verso": "Pena não superior a 4 anos e crime sem violência ou grave ameaça (ou crime culposo, qualquer pena), réu não reincidente em crime doloso e circunstâncias judiciais favoráveis.", "explicacao": "CP, art. 44."}, {"id": 1000032, "trilha": "policial", "materia": "pen", "assunto": "Penas", "tipo": "pergunta", "frente": "Depois de quanto tempo a condenação anterior deixa de gerar reincidência?", "verso": "5 anos, contados do cumprimento ou extinção da pena.", "explicacao": "CP, art. 64, I (período depurador)."}, {"id": 1000033, "trilha": "policial", "materia": "pen", "assunto": "Penas", "tipo": "pergunta", "frente": "Que idades geram atenuante genérica?", "verso": "Menor de 21 anos na data do fato ou maior de 70 anos na data da sentença.", "explicacao": "CP, art. 65, I."}, {"id": 1000034, "trilha": "policial", "materia": "pen", "assunto": "Prescrição", "tipo": "lacuna", "frente": "Reduzem-se de ____ os prazos de prescrição quando o criminoso era menor de 21 anos na data do crime ou maior de 70 na data da sentença.", "verso": "metade", "explicacao": "CP, art. 115."}, {"id": 1000035, "trilha": "policial", "materia": "pen", "assunto": "Prescrição", "tipo": "pergunta", "frente": "Quais crimes a Constituição declara imprescritíveis?", "verso": "Racismo e ação de grupos armados, civis ou militares, contra a ordem constitucional e o Estado Democrático.", "explicacao": "CF, art. 5º, XLII e XLIV."}, {"id": 1000036, "trilha": "policial", "materia": "pen", "assunto": "Constituição penal", "tipo": "pergunta", "frente": "Quais crimes são inafiançáveis e insuscetíveis de graça ou anistia (CF, art. 5º, XLIII)?", "verso": "Tortura, tráfico de drogas, terrorismo e crimes hediondos (“3TH”).", "explicacao": "CF, art. 5º, XLIII."}, {"id": 1000037, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a vida", "tipo": "pergunta", "frente": "Qual a pena do homicídio simples?", "verso": "Reclusão de 6 a 20 anos.", "explicacao": "CP, art. 121, caput."}, {"id": 1000038, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a vida", "tipo": "pergunta", "frente": "Qual a pena do homicídio qualificado?", "verso": "Reclusão de 12 a 30 anos.", "explicacao": "CP, art. 121, § 2º. É crime hediondo."}, {"id": 1000039, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a vida", "tipo": "pergunta", "frente": "Como o feminicídio está previsto hoje no Código Penal?", "verso": "Como crime autônomo (art. 121-A), com pena de reclusão de 20 a 40 anos.", "explicacao": "Lei 14.994/2024 (pacote antifeminicídio). Antes era qualificadora do homicídio."}, {"id": 1000040, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a vida", "tipo": "pergunta", "frente": "Quando o homicídio é privilegiado?", "verso": "Quando cometido por relevante valor social ou moral, ou sob domínio de violenta emoção logo em seguida a injusta provocação da vítima. Reduz a pena de 1/6 a 1/3.", "explicacao": "CP, art. 121, § 1º."}, {"id": 1000041, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a vida", "tipo": "pergunta", "frente": "O que caracteriza o infanticídio?", "verso": "Matar o próprio filho, sob influência do estado puerperal, durante o parto ou logo após.", "explicacao": "CP, art. 123."}, {"id": 1000042, "trilha": "policial", "materia": "pen", "assunto": "Lesão corporal", "tipo": "pares", "frente": "Diferencie lesão corporal grave de gravíssima (exemplos).", "verso": "Grave: incapacidade para ocupações habituais por mais de 30 dias, perigo de vida, debilidade permanente, aceleração de parto. Gravíssima: incapacidade permanente para o trabalho, enfermidade incurável, perda ou inutilização de membro, sentido ou função, deformidade permanente, aborto.", "explicacao": "CP, art. 129, §§ 1º e 2º. Debilidade = grave; perda = gravíssima."}, {"id": 1000043, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a honra", "tipo": "pares", "frente": "Calúnia, difamação e injúria: qual a diferença?", "verso": "Calúnia: imputar falsamente fato definido como crime. Difamação: imputar fato ofensivo à reputação. Injúria: ofender a dignidade ou o decoro, sem imputar fato.", "explicacao": "CP, arts. 138, 139 e 140. Calúnia e difamação atingem a honra objetiva; injúria, a subjetiva."}, {"id": 1000044, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra o patrimônio", "tipo": "pergunta", "frente": "Qual a pena do furto simples?", "verso": "Reclusão de 1 a 4 anos e multa.", "explicacao": "CP, art. 155, caput."}, {"id": 1000045, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra o patrimônio", "tipo": "pergunta", "frente": "Qual o aumento do furto praticado durante o repouso noturno?", "verso": "Aumenta de 1/3.", "explicacao": "CP, art. 155, § 1º."}, {"id": 1000046, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra o patrimônio", "tipo": "pergunta", "frente": "Quais os requisitos do furto privilegiado?", "verso": "Criminoso primário e coisa furtada de pequeno valor. O juiz pode trocar reclusão por detenção, reduzir de 1/3 a 2/3 ou aplicar só multa.", "explicacao": "CP, art. 155, § 2º."}, {"id": 1000047, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra o patrimônio", "tipo": "pergunta", "frente": "Quais são as qualificadoras clássicas do furto (§ 4º)?", "verso": "Destruição ou rompimento de obstáculo; abuso de confiança, fraude, escalada ou destreza; chave falsa; concurso de duas ou mais pessoas.", "explicacao": "CP, art. 155, § 4º. Pena de 2 a 8 anos."}, {"id": 1000048, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra o patrimônio", "tipo": "pergunta", "frente": "Qual a pena do roubo simples?", "verso": "Reclusão de 4 a 10 anos e multa.", "explicacao": "CP, art. 157, caput."}, {"id": 1000049, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra o patrimônio", "tipo": "pergunta", "frente": "O que é roubo impróprio?", "verso": "Quando a violência ou grave ameaça é empregada logo depois de subtraída a coisa, para assegurar a impunidade ou a detenção da coisa.", "explicacao": "CP, art. 157, § 1º. No roubo próprio, a violência vem antes ou durante a subtração."}, {"id": 1000050, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra o patrimônio", "tipo": "pares", "frente": "Roubo com arma de fogo: qual o aumento? E se a arma for de uso restrito ou proibido?", "verso": "Arma de fogo: aumenta 2/3. Arma de uso restrito ou proibido: aplica-se em dobro.", "explicacao": "CP, art. 157, § 2º-A, I, e § 2º-B."}, {"id": 1000051, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra o patrimônio", "tipo": "pergunta", "frente": "Qual a pena do latrocínio e quem o julga?", "verso": "Reclusão de 20 a 30 anos. É julgado pelo juiz singular, não pelo júri.", "explicacao": "CP, art. 157, § 3º, II. Súmula 603 do STF: é crime contra o patrimônio."}, {"id": 1000052, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra o patrimônio", "tipo": "pares", "frente": "Qual a diferença entre extorsão e roubo?", "verso": "Na extorsão, a vantagem depende de uma conduta da própria vítima (ela faz, tolera ou deixa de fazer algo). No roubo, o agente subtrai a coisa por si.", "explicacao": "CP, arts. 157 e 158."}, {"id": 1000053, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra o patrimônio", "tipo": "pergunta", "frente": "Como se tipifica o “sequestro relâmpago”?", "verso": "Extorsão com restrição da liberdade da vítima, condição necessária para obter a vantagem.", "explicacao": "CP, art. 158, § 3º."}, {"id": 1000054, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra o patrimônio", "tipo": "pares", "frente": "Qual a diferença entre apropriação indébita e furto?", "verso": "Na apropriação indébita, o agente já tem a posse ou detenção lícita da coisa e passa a agir como dono. No furto, ele subtrai coisa que não estava com ele.", "explicacao": "CP, arts. 155 e 168."}, {"id": 1000055, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra o patrimônio", "tipo": "pergunta", "frente": "Qual é, em regra, a ação penal no estelionato?", "verso": "Pública condicionada à representação.", "explicacao": "CP, art. 171, § 5º (Pacote Anticrime). É incondicionada se a vítima for a Administração Pública, criança ou adolescente, pessoa com deficiência mental, maior de 70 anos ou incapaz."}, {"id": 1000056, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra o patrimônio", "tipo": "pergunta", "frente": "O que é escusa absolutória nos crimes patrimoniais?", "verso": "Isenção de pena para quem comete crime patrimonial sem violência ou grave ameaça contra cônjuge (na constância da sociedade conjugal), ascendente ou descendente.", "explicacao": "CP, art. 181. Não se aplica se a vítima tiver 60 anos ou mais (art. 183)."}, {"id": 1000057, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra o patrimônio", "tipo": "pergunta", "frente": "O que é receptação?", "verso": "Adquirir, receber, transportar, conduzir ou ocultar, em proveito próprio ou alheio, coisa que sabe ser produto de crime, ou influir para que terceiro de boa-fé a adquira.", "explicacao": "CP, art. 180."}, {"id": 1000058, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a dignidade sexual", "tipo": "pergunta", "frente": "Até que idade a vítima é considerada vulnerável no art. 217-A do CP?", "verso": "Menor de 14 anos.", "explicacao": "CP, art. 217-A. O consentimento da vítima ou experiência anterior é irrelevante (§ 5º)."}, {"id": 1000059, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a Administração", "tipo": "pergunta", "frente": "O que é peculato (art. 312)?", "verso": "O funcionário público se apropriar de dinheiro, valor ou bem móvel de que tem a posse em razão do cargo, ou desviá-lo em proveito próprio ou alheio.", "explicacao": "CP, art. 312. Peculato-furto: subtrai valendo-se da facilidade do cargo (§ 1º)."}, {"id": 1000060, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a Administração", "tipo": "pergunta", "frente": "No peculato culposo, qual o efeito da reparação do dano?", "verso": "Antes da sentença irrecorrível: extingue a punibilidade. Depois: reduz a pena pela metade.", "explicacao": "CP, art. 312, § 3º."}, {"id": 1000061, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a Administração", "tipo": "pares", "frente": "Concussão x corrupção passiva: qual o verbo de cada uma?", "verso": "Concussão: EXIGIR vantagem indevida. Corrupção passiva: SOLICITAR, RECEBER ou ACEITAR PROMESSA de vantagem.", "explicacao": "CP, arts. 316 e 317."}, {"id": 1000062, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a Administração", "tipo": "pergunta", "frente": "O que é prevaricação?", "verso": "Retardar ou deixar de praticar ato de ofício, ou praticá-lo contra disposição de lei, para satisfazer interesse ou sentimento pessoal.", "explicacao": "CP, art. 319."}, {"id": 1000063, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a Administração", "tipo": "pergunta", "frente": "Quem é funcionário público para fins penais?", "verso": "Quem, embora transitoriamente ou sem remuneração, exerce cargo, emprego ou função pública.", "explicacao": "CP, art. 327. Equipara-se quem trabalha em entidade paraestatal ou empresa contratada para atividade típica (§ 1º)."}, {"id": 1000064, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a Administração", "tipo": "pares", "frente": "Resistência x desobediência: qual a diferença?", "verso": "Resistência: opor-se à execução de ato legal mediante violência ou ameaça ao funcionário. Desobediência: desobedecer ordem legal, sem violência.", "explicacao": "CP, arts. 329 e 330."}, {"id": 1000065, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a Administração", "tipo": "pergunta", "frente": "O que é denunciação caluniosa?", "verso": "Dar causa à instauração de investigação, processo ou ação contra alguém, imputando-lhe crime (ou infração) de que o sabe inocente.", "explicacao": "CP, art. 339. Não confundir com calúnia, que só ofende a honra."}, {"id": 1000066, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a Administração", "tipo": "certo_errado", "frente": "Certo ou errado? O preso que foge sem usar violência contra a pessoa comete crime.", "verso": "Errado. A fuga sem violência não é crime, mas é falta grave na execução.", "explicacao": "CP, art. 352 (evasão exige violência) e LEP, art. 50, II."}, {"id": 1000067, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a Administração", "tipo": "pergunta", "frente": "O que é desacato?", "verso": "Desacatar funcionário público no exercício da função ou em razão dela.", "explicacao": "CP, art. 331. O STF considerou o tipo compatível com a Constituição (ADPF 496)."}, {"id": 1000068, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a Administração", "tipo": "pares", "frente": "Corrupção ativa x corrupção passiva: quem pratica cada uma?", "verso": "Ativa: o particular que oferece ou promete vantagem indevida ao funcionário. Passiva: o funcionário que solicita, recebe ou aceita a promessa.", "explicacao": "CP, arts. 333 e 317. Exceção à teoria monista: cada um responde por um crime."}, {"id": 1000069, "trilha": "policial", "materia": "pen", "assunto": "Extinção da punibilidade", "tipo": "pergunta", "frente": "Cite causas de extinção da punibilidade do art. 107 do CP.", "verso": "Morte do agente, anistia, graça ou indulto, abolitio criminis, prescrição, decadência ou perempção, renúncia ou perdão aceito (ação privada), retratação (quando a lei admite) e perdão judicial.", "explicacao": "CP, art. 107."}, {"id": 1000070, "trilha": "policial", "materia": "ppen", "assunto": "Inquérito policial", "tipo": "pergunta", "frente": "Quais as características do inquérito policial?", "verso": "Procedimento administrativo, escrito, inquisitivo, sigiloso, oficioso, indisponível para a autoridade policial e dispensável para a ação penal.", "explicacao": "CPP, arts. 4º a 23."}, {"id": 1000071, "trilha": "policial", "materia": "ppen", "assunto": "Inquérito policial", "tipo": "pergunta", "frente": "Quem preside o inquérito policial?", "verso": "O delegado de polícia.", "explicacao": "Lei 12.830/2013, art. 2º, § 1º."}, {"id": 1000072, "trilha": "policial", "materia": "ppen", "assunto": "Inquérito policial", "tipo": "pares", "frente": "Prazo do inquérito no CPP: indiciado preso x solto.", "verso": "Preso: 10 dias. Solto: 30 dias (prorrogável pelo juiz).", "explicacao": "CPP, art. 10."}, {"id": 1000073, "trilha": "policial", "materia": "ppen", "assunto": "Inquérito policial", "tipo": "pergunta", "frente": "Prazo do inquérito da Polícia Federal com indiciado preso:", "verso": "15 dias, prorrogáveis por mais 15.", "explicacao": "Lei 5.010/1966, art. 66."}, {"id": 1000074, "trilha": "policial", "materia": "ppen", "assunto": "Inquérito policial", "tipo": "pares", "frente": "Prazo do inquérito na Lei de Drogas: preso x solto.", "verso": "Preso: 30 dias. Solto: 90 dias. Os dois podem ser duplicados pelo juiz.", "explicacao": "Lei 11.343/2006, art. 51."}, {"id": 1000075, "trilha": "policial", "materia": "ppen", "assunto": "Inquérito policial", "tipo": "certo_errado", "frente": "Certo ou errado? A autoridade policial pode mandar arquivar os autos de inquérito.", "verso": "Errado.", "explicacao": "CPP, art. 17."}, {"id": 1000076, "trilha": "policial", "materia": "ppen", "assunto": "Inquérito policial", "tipo": "pergunta", "frente": "Na ação penal privada, como se instaura o inquérito?", "verso": "Só a requerimento de quem tenha qualidade para propor a ação (o ofendido ou seu representante).", "explicacao": "CPP, art. 5º, § 5º. Na condicionada, depende de representação (§ 4º)."}, {"id": 1000077, "trilha": "policial", "materia": "ppen", "assunto": "Inquérito policial", "tipo": "pergunta", "frente": "O indiciamento é ato de quem?", "verso": "Privativo do delegado de polícia, por ato fundamentado, com análise técnico-jurídica do fato.", "explicacao": "Lei 12.830/2013, art. 2º, § 6º."}, {"id": 1000078, "trilha": "policial", "materia": "ppen", "assunto": "Inquérito policial", "tipo": "pergunta", "frente": "O que garante a Súmula Vinculante 14?", "verso": "Acesso amplo do defensor aos elementos de prova já documentados no procedimento investigatório, no interesse do representado.", "explicacao": "Súmula Vinculante 14 do STF. Diligências em andamento podem ficar sob sigilo."}, {"id": 1000079, "trilha": "policial", "materia": "ppen", "assunto": "Inquérito policial", "tipo": "certo_errado", "frente": "Certo ou errado? A incomunicabilidade do indiciado por até 3 dias (CPP, art. 21) foi recepcionada pela Constituição.", "verso": "Errado. Prevalece que não foi recepcionada: a CF veda a incomunicabilidade até no estado de defesa.", "explicacao": "CF, art. 136, § 3º, IV."}, {"id": 1000080, "trilha": "policial", "materia": "ppen", "assunto": "Inquérito policial", "tipo": "pergunta", "frente": "O juiz pode condenar com base apenas no inquérito?", "verso": "Não. Não pode fundamentar a decisão exclusivamente nos elementos informativos da investigação, ressalvadas as provas cautelares, não repetíveis e antecipadas.", "explicacao": "CPP, art. 155."}, {"id": 1000081, "trilha": "policial", "materia": "ppen", "assunto": "Inquérito policial", "tipo": "pergunta", "frente": "Arquivado o inquérito a pedido do MP, pode-se depois iniciar a ação penal?", "verso": "Só com novas provas.", "explicacao": "Súmula 524 do STF e CPP, art. 18."}, {"id": 1000082, "trilha": "policial", "materia": "ppen", "assunto": "Prisão em flagrante", "tipo": "pares", "frente": "Flagrante próprio, impróprio e presumido: o que é cada um?", "verso": "Próprio: está cometendo ou acaba de cometer. Impróprio: é perseguido logo após, em situação que faça presumir a autoria. Presumido (ficto): é encontrado logo depois com instrumentos, armas, objetos ou papéis que façam presumir a autoria.", "explicacao": "CPP, art. 302."}, {"id": 1000083, "trilha": "policial", "materia": "ppen", "assunto": "Prisão em flagrante", "tipo": "pares", "frente": "Flagrante preparado x flagrante esperado: qual é válido?", "verso": "Preparado (provocado pela polícia): não há crime (Súmula 145 do STF). Esperado (a polícia só aguarda o crime acontecer): é válido.", "explicacao": "Súmula 145 do STF."}, {"id": 1000084, "trilha": "policial", "materia": "ppen", "assunto": "Prisão em flagrante", "tipo": "pergunta", "frente": "O que é flagrante diferido ou retardado?", "verso": "A ação controlada: a polícia retarda a intervenção para agir no momento mais eficaz para a prova.", "explicacao": "Lei 12.850/2013, art. 8º, e Lei 11.343/2006, art. 53, II."}, {"id": 1000085, "trilha": "policial", "materia": "ppen", "assunto": "Prisão em flagrante", "tipo": "pergunta", "frente": "Em quanto tempo o auto de prisão em flagrante vai ao juiz e a nota de culpa ao preso?", "verso": "Em até 24 horas.", "explicacao": "CPP, art. 306, §§ 1º e 2º. A prisão deve ser comunicada imediatamente ao juiz, ao MP e à família."}, {"id": 1000086, "trilha": "policial", "materia": "ppen", "assunto": "Prisão em flagrante", "tipo": "pergunta", "frente": "Em que prazo deve ocorrer a audiência de custódia?", "verso": "Em até 24 horas após a prisão.", "explicacao": "CPP, art. 310."}, {"id": 1000087, "trilha": "policial", "materia": "ppen", "assunto": "Fiança", "tipo": "pergunta", "frente": "Até que pena o delegado pode conceder fiança?", "verso": "Infrações cuja pena privativa de liberdade máxima não seja superior a 4 anos.", "explicacao": "CPP, art. 322. Acima disso, só o juiz."}, {"id": 1000088, "trilha": "policial", "materia": "ppen", "assunto": "Fiança", "tipo": "pergunta", "frente": "Quais crimes são inafiançáveis pelo CPP?", "verso": "Racismo, tortura, tráfico de drogas, terrorismo, crimes hediondos e ação de grupos armados contra a ordem constitucional.", "explicacao": "CPP, art. 323."}, {"id": 1000089, "trilha": "policial", "materia": "ppen", "assunto": "Prisão preventiva", "tipo": "pergunta", "frente": "Quais os fundamentos da prisão preventiva?", "verso": "Garantia da ordem pública ou econômica, conveniência da instrução criminal ou assegurar a aplicação da lei penal, com prova do crime, indício suficiente de autoria e perigo gerado pela liberdade do imputado.", "explicacao": "CPP, art. 312."}, {"id": 1000090, "trilha": "policial", "materia": "ppen", "assunto": "Prisão preventiva", "tipo": "certo_errado", "frente": "Certo ou errado? Após o Pacote Anticrime, o juiz pode decretar a preventiva de ofício.", "verso": "Errado. Só a requerimento do MP, do querelante ou do assistente, ou por representação da autoridade policial.", "explicacao": "CPP, art. 311."}, {"id": 1000091, "trilha": "policial", "materia": "ppen", "assunto": "Prisão preventiva", "tipo": "pergunta", "frente": "De quanto em quanto tempo a necessidade da preventiva deve ser revista?", "verso": "A cada 90 dias, por decisão fundamentada, de ofício.", "explicacao": "CPP, art. 316, parágrafo único."}, {"id": 1000092, "trilha": "policial", "materia": "ppen", "assunto": "Prisão temporária", "tipo": "pares", "frente": "Prazo da prisão temporária: regra x crimes hediondos.", "verso": "Regra: 5 dias, prorrogáveis por mais 5. Hediondos e equiparados: 30 dias, prorrogáveis por mais 30.", "explicacao": "Lei 7.960/1989, art. 2º, e Lei 8.072/1990, art. 2º, § 4º."}, {"id": 1000093, "trilha": "policial", "materia": "ppen", "assunto": "Prisão temporária", "tipo": "pergunta", "frente": "Em que fase cabe a prisão temporária?", "verso": "Apenas na investigação (inquérito policial).", "explicacao": "Lei 7.960/1989."}, {"id": 1000094, "trilha": "policial", "materia": "ppen", "assunto": "Cautelares", "tipo": "pergunta", "frente": "Cite medidas cautelares diversas da prisão.", "verso": "Comparecimento periódico em juízo, proibição de frequentar lugares, proibição de contato, proibição de ausentar-se da comarca, recolhimento domiciliar noturno, suspensão da função pública, internação provisória, fiança e monitoração eletrônica.", "explicacao": "CPP, art. 319."}, {"id": 1000095, "trilha": "policial", "materia": "ppen", "assunto": "Cautelares", "tipo": "pergunta", "frente": "Em que casos o juiz pode substituir a preventiva por prisão domiciliar?", "verso": "Maior de 80 anos, extremamente debilitado por doença grave, imprescindível aos cuidados de menor de 6 anos ou pessoa com deficiência, gestante, mulher com filho de até 12 anos incompletos ou homem único responsável por filho dessa idade.", "explicacao": "CPP, art. 318."}, {"id": 1000096, "trilha": "policial", "materia": "ppen", "assunto": "Ação penal", "tipo": "pergunta", "frente": "Quem é o titular da ação penal pública?", "verso": "O Ministério Público.", "explicacao": "CF, art. 129, I."}, {"id": 1000097, "trilha": "policial", "materia": "ppen", "assunto": "Ação penal", "tipo": "pares", "frente": "Prazo para o MP oferecer a denúncia: réu preso x solto.", "verso": "Preso: 5 dias. Solto: 15 dias.", "explicacao": "CPP, art. 46."}, {"id": 1000098, "trilha": "policial", "materia": "ppen", "assunto": "Ação penal", "tipo": "pergunta", "frente": "Qual o prazo decadencial para queixa ou representação?", "verso": "6 meses, contados do dia em que o ofendido souber quem é o autor do crime.", "explicacao": "CPP, art. 38, e CP, art. 103."}, {"id": 1000099, "trilha": "policial", "materia": "ppen", "assunto": "Ação penal", "tipo": "pergunta", "frente": "Quando cabe ação penal privada subsidiária da pública?", "verso": "Quando o MP não oferece a denúncia no prazo legal (inércia).", "explicacao": "CF, art. 5º, LIX, e CPP, art. 29. Não cabe se o MP pediu arquivamento."}, {"id": 1000100, "trilha": "policial", "materia": "ppen", "assunto": "Ação penal", "tipo": "pares", "frente": "Princípios da ação pública x ação privada.", "verso": "Pública: obrigatoriedade e indisponibilidade. Privada: oportunidade (conveniência) e disponibilidade. As duas são indivisíveis.", "explicacao": "Na privada, a renúncia em relação a um autor se estende a todos (CPP, art. 49)."}]$c$::jsonb) as x(id integer, trilha text, materia text, assunto text, tipo text, frente text, verso text, explicacao text)
on conflict (id) do update set trilha = excluded.trilha, materia = excluded.materia, assunto = excluded.assunto, tipo = excluded.tipo,
  frente = excluded.frente, verso = excluded.verso, explicacao = excluded.explicacao, ativa = true, atualizado_em = now();

select count(*) as cartoes_policial_no_banco from public.cartoes where trilha = 'policial' and ativa;
